sys_ux_data_broker_transform.script:
function transform(input) {

    var leaderboard = [];

    if (!input || !input.quizSessionId) {
        return leaderboard;
    }

    var response = new GlideRecord(
        "x_1892173_stopwa_0_buzzer_response"
    );

    // Get responses for the current Quiz Session
    response.addQuery(
        "quiz_session",
        input.quizSessionId
    );

    // Ignore responses where timing was not calculated
    response.addNotNullQuery("response_time");

    // Ignore invalid zero response times
    response.addQuery(
        "response_time",
        ">",
        "0"
    );

    // Fastest response first
    response.orderBy("response_time");

    response.query();

    while (response.next()) {

        leaderboard.push({
            participantName: response.getDisplayValue("participant"),
            responseTime: response.getValue("response_time"),
            buzzerTime: response.getDisplayValue("buzzer_time"),
            runNumber: response.getValue("run_number")
        });
    }

    return leaderboard;
}
